const item = $input.first(); 

// --- CONFIGURAÇÕES ---
const DIA_DO_PAGAMENTO = 25; 
// ---------------------

const saldoAtual = item.json.SALDO || 0; 

// 1. Descobre as datas (Hoje e Pagamento)
const hoje = new Date();
let dataPagamento = new Date(hoje.getFullYear(), hoje.getMonth(), DIA_DO_PAGAMENTO);

// Se já passou do dia 25, joga o pagamento para o mês que vem
if (hoje.getDate() >= DIA_DO_PAGAMENTO) {
  dataPagamento.setMonth(dataPagamento.getMonth() + 1);
}

// 2. CONTA QUANTAS SEMANAS (DOMINGOS) EXISTEM ATÉ LÁ
// Começamos com 1 porque você precisa de dinheiro para a semana atual (de hoje até o próximo sábado)
let numeroDeSemanas = 1;
let cursorData = new Date(hoje);

// Vamos caminhar dia por dia no calendário até chegar no pagamento
while (cursorData < dataPagamento) {
    cursorData.setDate(cursorData.getDate() + 1); // Avança um dia

    // Se o dia for Domingo (0) e ainda for antes do pagamento, soma uma semana
    if (cursorData.getDay() === 0 && cursorData < dataPagamento) {
        numeroDeSemanas++;
    }
}

// 3. Faz a divisão do dinheiro pelos potes semanais
const metaSemanal = saldoAtual / numeroDeSemanas;

// Para o diário, dividimos a meta semanal por 7 (apenas para referência)
const metaDiaria = metaSemanal / 7;

// Funçãozinha de formatar dinheiro
function formatarDinheiro(valor) {
    return valor.toFixed(2).replace('.', ',');
}

// Calcula dias totais só para exibir na mensagem
const diferencaTempo = dataPagamento - hoje;
let diasFaltantes = Math.ceil(diferencaTempo / (1000 * 60 * 60 * 24));

return {
  json: {
    ...item.json,
    dias_restantes: diasFaltantes,
    semanas_restantes: numeroDeSemanas, // Criei essa var se quiser usar na msg
    pode_gastar_hoje: formatarDinheiro(metaDiaria),
    pode_gastar_semana: formatarDinheiro(metaSemanal)
  }
}

